// config.js: what the shared map-quiz engine (main.js, contract.js) needs
// to know about Deutschland-Quiz: the data (states.js, generated by
// tools/build_map.py) and every text the engine shows, in German. Static
// text (title, help, button labels before the script runs) is in
// index.html. Contract: shared/map-quiz/README.md.
//
// The asked name links to its German Wikipedia article (the capital's in
// the capitals round; titles from states.js: wiki, capitalWiki).
import { MAP, STATES } from './states.js';
import { wikipediaUrl } from './wiki.js';

const fehler = (n) => (n ? ` · ${n} Fehlklick${n === 1 ? '' : 's'}` : ' · ohne Fehlklick');
// A German Wikipedia article's URL from its title (wiki.js, the engine's
// helper: spaces as _, ? # % & + stay part of the title).
const wiki = (title) => wikipediaUrl('de', title);

export default {
  map: MAP,
  items: STATES,
  rounds: [
    {
      key: 'states',
      label: 'Länder',
      prompt: 'Finde das Land',
      ask: (s) => s.name,
      miss: (s) => s.name,
      link: (s) => wiki(s.wiki),
      done: ({ total, misses }) =>
        `Alle ${total} Länder gefunden${fehler(misses)}. Jetzt die ${STATES.length} Landeshauptstädte: finde das Land dazu.`,
    },
    {
      // Asks every state's capital, the city states' too. A misclick shows
      // name · capital, or just the name where they're the same (Berlin).
      key: 'capitals',
      label: 'Hauptstädte',
      prompt: 'Finde das Land mit der Hauptstadt',
      ask: (s) => s.capital,
      miss: (s) => (s.capital === s.name ? s.name : `${s.name} · ${s.capital}`),
      link: (s) => wiki(s.capitalWiki),
      done: ({ total, misses }) => `Alle ${total} Hauptstädte gefunden${fehler(misses)}. Wieder die Länder, neu gemischt.`,
    },
  ],
  text: {
    intro: {
      mouse: 'Klicke auf das gesuchte Land: zuerst die Länder, dann die Landeshauptstädte. Zoomen mit dem Mausrad oder zwei Fingern, verschieben durch Ziehen.',
      touch: 'Tippe auf das gesuchte Land: zuerst die Länder, dann die Landeshauptstädte. Zoomen mit zwei Fingern, verschieben durch Ziehen.',
    },
    newGame: 'Neues Spiel: Zähler auf null, zuerst die Länder.',
    reset: 'Quiz zurücksetzen',
    resetArmed: 'Wirklich zurücksetzen? Zähler und Farben werden gelöscht',
    mapError: 'Das Quiz konnte nicht geladen werden. Bitte lade die Seite neu.',
    theme: (other, override) => {
      const to = `In den ${other === 'dark' ? 'dunklen' : 'hellen'} Modus wechseln`;
      return {
        label: to,
        title: override ? `Zurück zur Systemeinstellung (${other === 'dark' ? 'dunkel' : 'hell'})` : to,
      };
    },
    link: (asked) => `${asked} auf Wikipedia (neuer Tab)`,
  },
  // besideHud: in landscape the full view fits left of the card and the
  // controls, so they never cover a Land. maxScale: the closest zoom, 3 px
  // per map unit (why 3: tools/README.md, "Map geometry"). ringMin: rings
  // keep their full radius at every zoom where they show (why:
  // tools/README.md, "Map geometry").
  view: { maxScale: 3, besideHud: true, ringMin: 7 },
};
